from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool

n = 35
N = 2*n
vpool = IDPool()
# x[v,i] = value v starts at position i (0-indexed), second copy at i+v+1
# i ranges 0..N-1-(v+1) = N-v-2

def var(v,i):
    return vpool.id(('x',v,i))

clauses = []
# Each value placed exactly once
for v in range(1,n+1):
    lits = [var(v,i) for i in range(0, N-v-1)]
    # at least one
    clauses.append(lits)
    # at most one - pairwise
    for a in range(len(lits)):
        for b in range(a+1,len(lits)):
            clauses.append([-lits[a],-lits[b]])

# Each position covered by exactly one (value,placement)
pos_lits = {p: [] for p in range(N)}
for v in range(1,n+1):
    for i in range(0, N-v-1):
        pos_lits[i].append(var(v,i))
        pos_lits[i+v+1].append(var(v,i))

for p in range(N):
    lits = pos_lits[p]
    clauses.append(lits)
    for a in range(len(lits)):
        for b in range(a+1,len(lits)):
            clauses.append([-lits[a],-lits[b]])

solver = Glucose4()
for c in clauses:
    solver.add_clause(c)

print("solving...")
print(solver.solve())
model = solver.get_model()
seq = [0]*N
for v in range(1,n+1):
    for i in range(0, N-v-1):
        if model[var(v,i)-1] > 0:
            seq[i] = v
            seq[i+v+1] = v
            break
print(seq)
# verify
for v in range(1,n+1):
    idxs = [k for k,x in enumerate(seq) if x==v]
    assert len(idxs)==2 and idxs[1]-idxs[0]==v+1
print("OK")
